---@class ActivityCrisisDojo
local ActivityCrisisDojo = Class("ActivityCrisisDojo")

function ActivityCrisisDojo:__init()
    self.schedule = {}
    self.entrance = {}
    self.quests = {}
    self.tasks = {}
end

---FillVo
---@param row TableML.TableFileRow
function ActivityCrisisDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
            if key == "quests" then
                self:HandleCountDownTime(self.quests.permanent[1])
                for i, v in pairs(self.quests.rotation) do
                    self:HandleCountDownTime(v)
                end
            end

            if key == "tasks" then
                self:HandleCountDownTime(self.tasks.permanent[1])
                for i, v in pairs(self.tasks.permanent[1].task) do
                    self:HandleCountDownTime(v)
                end

                for k, v in pairs(self.tasks.rotation) do
                    self:HandleCountDownTime(v)
                    for i, j in pairs(v.task) do
                        self:HandleCountDownTime(j)
                    end
                end
            end
        end
    end
end

function ActivityCrisisDojo:HandleCountDownTime(data)
    if data.limitCountdown and data.limitCountdown > 0 then
        data.limitCountdown = data.limitCountdown + os.time()
    end

    if data.unlockCountdown and data.unlockCountdown > 0 then
        data.unlockCountdown = data.unlockCountdown + os.time()
    end
end

function ActivityCrisisDojo:GetEntranceConfig()
    return self.entrance
end

function ActivityCrisisDojo:GetNormalQuestData()
    return self.quests.permanent[1]
end

function ActivityCrisisDojo:GetNormalQuest()
    return self.quests.permanent
end

function ActivityCrisisDojo:GetReceivedTaskIds()
    return self.quests.receivedTaskIds
end
function ActivityCrisisDojo:GetCompletedTaskIds()
    return self.quests.completedTaskIds
end
function ActivityCrisisDojo:GetRotationQuest()
    return self.quests.rotation
end

function ActivityCrisisDojo:GetTasks()
    return self.tasks
end

function ActivityCrisisDojo:IsHaveTaskRedPoint()
    return self.quests.permanentTips == 0 or  self.quests.rotationTips == 0
end

function ActivityCrisisDojo:__delete()
    self.schedule = nil
    self.entrance = nil
    self.quests = nil
    self.tasks = nil
end

return ActivityCrisisDojo